for vid, s in src.items():
    P, N, Q, A, last = T[vid]
    assert len(P) == len(s['phrases']) and len(N) == len(s['nouns']), vid
    ptxt = [p['text'] for p in s['phrases']]
    rec = []
    for i, r in enumerate(s['recall']):
        if r in ptxt: rec.append(P[ptxt.index(r)])
        elif r in s['nouns']: rec.append(N[s['nouns'].index(r)])
        else:
            assert i == len(s['recall']) - 1, (vid, r); rec.append(last)
    out[vid] = {"phrases": P, "nouns": N, "question": Q, "answer": A, "captions": {}, "recall": rec}
json.dump(out, open(os.path.join(H, 'de.json'), 'w'), ensure_ascii=False, indent=1)
print(len(out))
